import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.orders.api.OrderSummary;
import com.wolinski.shop.platform.ShopProblem;
import com.wolinski.shop.shipping.api.CarrierGateway;
import java.time.Instant;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class OrderService implements OrderFacade {

    private final OrderRepository orders;
    private final CarrierGateway carrier;
    private final TransactionTemplate transactions;

    public OrderService(OrderRepository orders, CarrierGateway carrier, PlatformTransactionManager transactionManager) {
        this.orders = orders;
        this.carrier = carrier;
        this.transactions = new TransactionTemplate(transactionManager);
    }

    @Override
    @Transactional
    public String place(String customerId, Money total, Instant placedAt) {
        Order order = new Order(UUID.randomUUID().toString(), customerId, total, placedAt);
        orders.save(order);
        return order.id();
    }

    /**
     * Not transactional: the carrier is called outside any transaction (ADR 5). The status change commits first,
     * then the shipment is booked, then the tracking number is stored. If the carrier refuses, the status is restored.
     */
    @Override
    public void confirm(String orderId) {
        Confirmation confirmation = transactions.execute(status -> {
            Order order = orders.get(orderId);
            Confirmation before = new Confirmation(order.status(), order.trackingNumber() == null);
            order.changeStatus("CONFIRMED");
            return before;
        });
        if (!confirmation.bookingNeeded()) {
            return;
        }

        String trackingNumber;
        try {
            trackingNumber = carrier.book(orderId);
        } catch (RuntimeException e) {
            restoreStatus(orderId, confirmation.previousStatus());
            throw new ShopProblem("shipment-not-booked", "The carrier did not book a shipment for " + orderId, e);
        }
        if (trackingNumber == null) {
            restoreStatus(orderId, confirmation.previousStatus());
            throw new ShopProblem("shipment-not-booked", "The carrier returned no tracking number for " + orderId);
        }

        transactions.executeWithoutResult(status -> orders.get(orderId).recordTrackingNumber(trackingNumber));
    }

    private void restoreStatus(String orderId, String status) {
        transactions.executeWithoutResult(tx -> orders.get(orderId).changeStatus(status));
    }

    /** The order's status before confirming, and whether a shipment still has to be booked. */
    private record Confirmation(String previousStatus, boolean bookingNeeded) {
    }

    @Override
    @Transactional
    public void cancel(String orderId) {
        orders.get(orderId).changeStatus("CANCELLED");
    }

    @Override
    @Transactional(readOnly = true)
    public OrderSummary summary(String orderId) {
        Order order = orders.get(orderId);
        return new OrderSummary(order.id(), order.customerId(), order.total(), order.status(), order.trackingNumber());
    }
}
}

