import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderSummary;
import com.wolinski.shop.platform.InMemoryTransactionManager;
import com.wolinski.shop.platform.ShopProblem;
import com.wolinski.shop.shipping.api.CarrierGateway;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    private final List<String> bookedWhileTransactionOpen = new ArrayList<>();
    private final List<String> booked = new ArrayList<>();
    private RuntimeException carrierFailure;
    private String carrierAnswer;
    private OrderService orders;
    private String orderId;

    @BeforeEach
    void setUp() {
        CarrierGateway carrier = orderId -> {
            if (InMemoryTransactionManager.isOpen()) {
                bookedWhileTransactionOpen.add(orderId);
            }
            booked.add(orderId);
            if (carrierFailure != null) {
                throw carrierFailure;
            }
            return carrierAnswer;
        };
        orders = new OrderService(new OrderRepository(), carrier, new InMemoryTransactionManager());
        orderId = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
        carrierAnswer = "TRK-1";
    }

    @Test
    void confirmBooksAShipmentAndStoresTheTrackingNumber() {
        orders.confirm(orderId);

        OrderSummary summary = orders.summary(orderId);
        assertEquals("CONFIRMED", summary.status());
        assertEquals("TRK-1", summary.trackingNumber());
        assertEquals(List.of(orderId), booked);
    }

    @Test
    void theCarrierIsCalledOutsideAnyTransaction() {
        orders.confirm(orderId);

        assertTrue(bookedWhileTransactionOpen.isEmpty());
    }

    @Test
    void aTrackingNumberIsNullUntilConfirmed() {
        assertNull(orders.summary(orderId).trackingNumber());
    }

    @Test
    void whenTheCarrierFailsTheOrderIsNotLeftConfirmed() {
        carrierFailure = new IllegalStateException("carrier timeout");

        ShopProblem problem = assertThrows(ShopProblem.class, () -> orders.confirm(orderId));

        assertEquals("shipment-not-booked", problem.code());
        OrderSummary summary = orders.summary(orderId);
        assertEquals("PLACED", summary.status());
        assertNull(summary.trackingNumber());
    }

    @Test
    void whenTheCarrierReturnsNoTrackingNumberTheOrderIsNotConfirmed() {
        carrierAnswer = null;

        assertThrows(ShopProblem.class, () -> orders.confirm(orderId));

        assertEquals("PLACED", orders.summary(orderId).status());
    }

    @Test
    void confirmingTwiceBooksOnlyOneShipment() {
        orders.confirm(orderId);
        orders.confirm(orderId);

        assertEquals(1, booked.size());
        assertFalse(orders.summary(orderId).trackingNumber() == null);
    }
}
}
